<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import { FileCode2, Play, Route, ScanSearch } from "lucide-vue-next";
import { NButton, NCard, NDrawer, NDrawerContent, NEmpty, NSelect, NSpin, NTag, NTree } from "naive-ui";
import { getApiDefinition, listApiDefinitions, listSourceScans, startSourceScan, streamSourceScanProgress, type ApiDefinition, type ScanProgressEvent, type SourceScan } from "@/api/source-scans";
import { listProjects, type Project } from "@/api/projects";

interface TreeNode { key: string; label: string; children?: TreeNode[]; }
const projects = ref<Project[]>([]); const scans = ref<SourceScan[]>([]); const definitions = ref<ApiDefinition[]>([]); const projectId = ref<string | null>(null); const scanId = ref<string | null>(null); const moduleKey = ref<string | null>(null); const selectedDefinition = ref<ApiDefinition | null>(null); const progress = ref<ScanProgressEvent | null>(null); const loading = ref(false); const starting = ref(false); const errorMessage = ref("");
const projectOptions = computed(() => projects.value.map((project) => ({ label: project.name, value: project.id })));
const scanOptions = computed(() => scans.value.map((scan) => ({ label: `版本 ${scan.scan_version} · ${scan.status}`, value: scan.id })));
const moduleTree = computed<TreeNode[]>(() => { const modules = new Map<string, ApiDefinition[]>(); for (const definition of definitions.value) { const moduleName = definition.controller_qualified_name?.split(".").slice(0, -1).join(".") || "未识别模块"; modules.set(moduleName, [...(modules.get(moduleName) ?? []), definition]); } return [...modules.entries()].map(([moduleName, entries]) => ({ key: moduleName, label: moduleName, children: entries.map((entry) => ({ key: entry.id, label: `${entry.method} ${entry.normalized_path}` })) })); });
const visibleDefinitions = computed(() => moduleKey.value === null ? definitions.value : definitions.value.filter((definition) => { const moduleName = definition.controller_qualified_name?.split(".").slice(0, -1).join(".") || "未识别模块"; return moduleName === moduleKey.value || definition.id === moduleKey.value; }));
const activeScan = computed(() => scans.value.find((scan) => scan.id === scanId.value) ?? null);
const drawerVisible = computed({ get: () => selectedDefinition.value !== null, set: (visible: boolean) => { if (!visible) selectedDefinition.value = null; } });
function statusType(status: SourceScan["status"]): "default" | "success" | "warning" | "error" | "info" { if (status === "succeeded") return "success"; if (status === "failed" || status === "cancelled") return "error"; if (status === "running") return "info"; return "warning"; }
function formatJson(value: Record<string, unknown> | unknown[]): string { return Object.keys(value).length === 0 ? "暂无" : JSON.stringify(value, null, 2); }
async function loadScans(): Promise<void> { if (projectId.value === null) return; scans.value = (await listSourceScans(projectId.value)).data; scanId.value = scans.value[0]?.id ?? null; }
async function loadDefinitions(): Promise<void> { if (projectId.value === null || scanId.value === null) { definitions.value = []; return; } loading.value = true; errorMessage.value = ""; try { definitions.value = (await listApiDefinitions(projectId.value, scanId.value)).data; } catch (error: unknown) { errorMessage.value = error instanceof Error ? error.message : "接口列表加载失败"; } finally { loading.value = false; } }
async function subscribeProgress(scan: SourceScan): Promise<void> { if (projectId.value === null) return; try { await streamSourceScanProgress(projectId.value, scan.id, (event) => { progress.value = event; if (["succeeded", "failed", "cancelled"].includes(event.scan_status)) { void loadScans(); void loadDefinitions(); } }); } catch (error: unknown) { errorMessage.value = error instanceof Error ? error.message : "扫描进度订阅失败"; } }
async function createScan(): Promise<void> { if (projectId.value === null) return; starting.value = true; errorMessage.value = ""; try { await startSourceScan(projectId.value); await loadScans(); } catch (error: unknown) { errorMessage.value = error instanceof Error ? error.message : "扫描创建失败"; } finally { starting.value = false; } }
async function openDefinition(definition: ApiDefinition): Promise<void> { if (projectId.value === null || scanId.value === null) return; try { selectedDefinition.value = (await getApiDefinition(projectId.value, scanId.value, definition.id)).data; } catch (error: unknown) { errorMessage.value = error instanceof Error ? error.message : "接口详情加载失败"; } }
function selectTree(keys: Array<string | number>): void { const key = keys[0]; moduleKey.value = typeof key === "string" ? key : null; const definition = definitions.value.find((item) => item.id === key); if (definition !== undefined) selectedDefinition.value = definition; }
watch(projectId, () => { moduleKey.value = null; progress.value = null; definitions.value = []; void loadScans(); }); watch(scanId, () => { moduleKey.value = null; progress.value = null; selectedDefinition.value = null; void loadDefinitions(); const scan = activeScan.value; if (scan?.status === "pending" || scan?.status === "running") void subscribeProgress(scan); }); onMounted(async () => { projects.value = (await listProjects()).data; });
</script>
<template>
  <section class="api-page"><header class="page-header"><div class="page-heading"><span class="page-rail" aria-hidden="true"></span><div><p class="page-kicker">扫描版本</p><h1>接口发现</h1><p>查看已扫描项目中的模块、接口来源与 OpenAPI 差异。</p></div></div><NButton type="primary" :loading="starting" :disabled="projectId === null" @click="createScan"><template #icon><Play :size="16" /></template>开始扫描</NButton></header>
    <NCard class="control-card" :bordered="false"><div class="controls"><label>项目<NSelect v-model:value="projectId" :options="projectOptions" placeholder="选择项目" /></label><label>扫描版本<NSelect v-model:value="scanId" :options="scanOptions" :disabled="projectId === null" placeholder="选择扫描版本" /></label></div><div v-if="activeScan !== null" class="scan-rail"><div><span>版本 {{ activeScan.scan_version }}</span><NTag size="small" :type="statusType(progress?.scan_status ?? activeScan.status)">{{ progress?.phase ?? activeScan.status }}</NTag></div><div class="progress-track"><span :style="{ width: `${progress?.progress ?? (activeScan.status === 'succeeded' ? 100 : 0)}%` }"></span></div><strong>{{ progress?.progress ?? (activeScan.status === 'succeeded' ? 100 : 0) }}%</strong></div><p v-if="errorMessage" class="error-message">{{ errorMessage }}</p></NCard>
    <div v-if="scanId !== null" class="discovery-grid"><NCard class="module-card" :bordered="false" title="模块 / 包"><NTree block-line default-expand-all :data="moduleTree" :selected-keys="moduleKey === null ? [] : [moduleKey]" @update:selected-keys="selectTree" /><NEmpty v-if="!moduleTree.length && !loading" size="small" description="当前版本未发现模块" /></NCard><NCard class="interfaces-card" :bordered="false"><template #header><div class="card-title"><span>接口列表</span><NTag size="small">{{ visibleDefinitions.length }}</NTag></div></template><NSpin :show="loading"><div v-if="visibleDefinitions.length" class="interface-list"><button v-for="definition in visibleDefinitions" :key="definition.id" class="interface-row" type="button" @click="openDefinition(definition)"><NTag size="small" :type="definition.is_conflicted ? 'error' : 'info'">{{ definition.method }}</NTag><span class="route-path">{{ definition.normalized_path }}</span><span class="symbol-name">{{ definition.method_qualified_name ?? definition.operation_id ?? "未识别符号" }}</span><Route :size="16" aria-hidden="true" /></button></div><NEmpty v-else description="当前筛选条件下没有接口" /></NSpin></NCard></div><NEmpty v-else class="page-empty" description="选择项目和扫描版本后查看接口发现结果"><template #icon><ScanSearch :size="36" /></template></NEmpty>
    <NDrawer v-model:show="drawerVisible" :width="620" placement="right"><NDrawerContent v-if="selectedDefinition !== null" :title="`${selectedDefinition.method} ${selectedDefinition.normalized_path}`" closable><div class="detail-section"><h2>来源定位</h2><dl><dt>来源文件</dt><dd><FileCode2 :size="16" />{{ selectedDefinition.source_file_path ?? "未关联来源文件" }}</dd><dt>控制器</dt><dd>{{ selectedDefinition.controller_qualified_name ?? "未识别" }}</dd><dt>方法符号</dt><dd>{{ selectedDefinition.method_qualified_name ?? "未识别" }}</dd></dl></div><div class="detail-section"><h2>接口定义</h2><pre>{{ formatJson(selectedDefinition.source_definition) }}</pre></div><div class="detail-section"><h2>OpenAPI 差异</h2><p v-if="!selectedDefinition.is_conflicted" class="muted-copy">未检测到差异。</p><pre v-else>{{ formatJson(selectedDefinition.conflicts) }}</pre></div><div class="detail-section"><h2>OpenAPI 定义</h2><pre>{{ formatJson(selectedDefinition.openapi_definition) }}</pre></div></NDrawerContent></NDrawer>
  </section>
</template>
<style scoped>
.api-page { display: grid; gap: 22px; }.page-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 24px; }.page-heading { display: flex; gap: 16px; }.page-rail { width: 3px; min-height: 72px; background: var(--color-primary); border-radius: var(--radius-sm); }.page-kicker { margin: 0 0 6px; color: var(--color-primary); font-size: 12px; font-weight: 650; }h1 { margin: 0; color: var(--color-text); font-size: 24px; letter-spacing: -0.025em; }.page-heading p:last-child { margin: 8px 0 0; color: var(--color-text-secondary); font-size: 14px; }.control-card, .module-card, .interfaces-card { border: 1px solid var(--color-border); border-radius: var(--radius-lg); box-shadow: var(--shadow-card); }.controls { display: flex; gap: 16px; }.controls label { display: grid; min-width: 240px; gap: 8px; color: var(--color-text-secondary); font-size: 12px; }.scan-rail { display: grid; grid-template-columns: auto minmax(80px, 1fr) auto; align-items: center; gap: 16px; margin-top: 20px; padding: 14px 16px; background: var(--color-surface-muted); border-radius: var(--radius-md); }.scan-rail > div:first-child { display: flex; gap: 10px; align-items: center; color: var(--color-text); font-size: 13px; }.progress-track { overflow: hidden; height: 5px; background: var(--color-border); border-radius: 999px; }.progress-track span { display: block; height: 100%; background: var(--color-primary); transition: width 180ms ease; }.scan-rail strong { color: var(--color-text-secondary); font-size: 12px; }.error-message { margin: 12px 0 0; color: var(--color-danger); font-size: 13px; }.discovery-grid { display: grid; grid-template-columns: minmax(230px, 0.7fr) minmax(0, 1.8fr); gap: 18px; }.card-title { display: flex; align-items: center; gap: 8px; }.interface-list { display: grid; }.interface-row { display: grid; grid-template-columns: auto minmax(160px, 1fr) minmax(160px, 1.1fr) auto; align-items: center; gap: 12px; width: 100%; padding: 14px 4px; color: var(--color-text); text-align: left; cursor: pointer; background: transparent; border: 0; border-bottom: 1px solid var(--color-border); }.interface-row:hover { color: var(--color-primary); }.route-path { font-family: var(--font-mono); font-size: 13px; }.symbol-name { overflow: hidden; color: var(--color-text-secondary); font-size: 12px; text-overflow: ellipsis; white-space: nowrap; }.page-empty { padding: 80px 0; }.detail-section { padding: 4px 0 20px; border-bottom: 1px solid var(--color-border); }.detail-section + .detail-section { padding-top: 20px; }.detail-section h2 { margin: 0 0 12px; color: var(--color-text); font-size: 14px; }.detail-section dl { display: grid; grid-template-columns: 82px minmax(0, 1fr); gap: 10px 12px; margin: 0; font-size: 13px; }.detail-section dt { color: var(--color-text-muted); }.detail-section dd { display: flex; gap: 7px; align-items: center; min-width: 0; margin: 0; color: var(--color-text-secondary); overflow-wrap: anywhere; }.detail-section pre { max-height: 220px; padding: 12px; overflow: auto; color: var(--color-text-secondary); font: 12px/1.6 var(--font-mono); white-space: pre-wrap; background: var(--color-surface-muted); border-radius: var(--radius-sm); }.muted-copy { margin: 0; color: var(--color-text-secondary); font-size: 13px; }@media (max-width: 900px) { .discovery-grid { grid-template-columns: 1fr; }.controls { flex-direction: column; }.controls label { min-width: 0; }.interface-row { grid-template-columns: auto minmax(0, 1fr) auto; }.symbol-name { display: none; } }@media (max-width: 640px) { .page-header { flex-direction: column; }.scan-rail { grid-template-columns: 1fr; gap: 10px; } }
</style>
